use super::*;
use semio_framework_os_kernel::{ArtifactSqliteSnapshot,sqlite_snapshot::*};
fn fixture()->Wfc2dSnapshot{let f:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🪶️sqlite/🔣️.json")).unwrap();let text=|v:&serde_json::Value|v.as_str().unwrap().to_string();let word=|v:&serde_json::Value|f64::from_bits(u64::from_str_radix(v.as_str().unwrap(),16).unwrap());let color=|v:&serde_json::Value|Wfc2dColor{r:v["r"].as_u64().unwrap() as u32,g:v["g"].as_u64().unwrap() as u32,b:v["b"].as_u64().unwrap() as u32,a:v["a"].as_u64().unwrap() as u32};let point=|v:&serde_json::Value|[word(&v[0]),word(&v[1])];Wfc2dSnapshot{schema:text(&f["schema"]),seed:f["seed"].as_str().unwrap().parse().unwrap(),tiles:f["tiles"].as_array().unwrap().iter().map(|t|{let m=&t["media"];let media=match m["kind"].as_str().unwrap(){"Empty"=>Wfc2dTileMedia::Empty,"Bitmap"=>Wfc2dTileMedia::Bitmap{width:m["width"].as_u64().unwrap() as u32,height:m["height"].as_u64().unwrap() as u32,palette:m["palette"].as_array().unwrap().iter().map(color).collect(),pixels:text(&m["pixels"])},"Vector"=>Wfc2dTileMedia::Vector{paths:m["paths"].as_array().unwrap().iter().map(|p|Wfc2dVectorPath{stroke_width:word(&p["strokeWidthBits"]),fill:p.get("fill").map(color),stroke:p.get("stroke").map(color),segments:p["segments"].as_array().unwrap().iter().map(|s|match s["kind"].as_str().unwrap(){"Move"=>Wfc2dPathSegment::Move{to:point(&s["toBits"])},"Line"=>Wfc2dPathSegment::Line{to:point(&s["toBits"])},"Quad"=>Wfc2dPathSegment::Quad{ctrl:point(&s["ctrlBits"]),to:point(&s["toBits"])},"Cubic"=>Wfc2dPathSegment::Cubic{ctrl1:point(&s["ctrl1Bits"]),ctrl2:point(&s["ctrl2Bits"]),to:point(&s["toBits"])},"Close"=>Wfc2dPathSegment::Close,_=>panic!("segment")}).collect()}).collect()},"Image"=>{let v=&m["target"];Wfc2dTileMedia::Image{child:store::ArtifactChild::new(text(&m["childId"]),store::os_io::ArtifactRef{artifact_id:text(&v["artifactId"]),dialect:store::os_io::ArtifactDialect{artifact_kind:text(&v["dialect"]["artifactKind"]),standard:text(&v["dialect"]["standard"]),subset:text(&v["dialect"]["subset"])}})}},_=>panic!("media")};Wfc2dTile{id:text(&t["id"]),label:t.get("label").map(text),weight:word(&t["weightBits"]),media}}).collect(),slots:f["slots"].as_array().unwrap().iter().map(|s|Wfc2dSlot{id:text(&s["id"]),x:word(&s["xBits"]),y:word(&s["yBits"]),width:word(&s["widthBits"]),height:word(&s["heightBits"]),pinned_tile_id:s.get("pinnedTileId").map(text)}).collect(),edges:f["edges"].as_array().unwrap().iter().map(|e|Wfc2dSlotEdge{id:text(&e["id"]),from_slot_id:text(&e["fromSlotId"]),to_slot_id:text(&e["toSlotId"]),relation:text(&e["relation"])}).collect(),rules:f["rules"].as_array().unwrap().iter().map(|r|Wfc2dRule{id:text(&r["id"]),tile_a_id:text(&r["tileAId"]),tile_b_id:text(&r["tileBId"]),relation:r.get("relation").map(text),allowed:r["allowed"].as_bool().unwrap()}).collect()}}
fn project(s:&Wfc2dSnapshot)->SqliteDatabase{s.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap()}
fn restore(d:&SqliteDatabase)->Result<Wfc2dSnapshot,String>{Wfc2dSnapshot::from_sqlite_database(d,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default()))}
#[test]fn sqlite_snapshot_wfc2d_all_owned_media_and_slot_words(){let s=fixture();let d=project(&s);let bytes=export_sqlite_database(&d,SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let actual=restore(&import_sqlite_database(&bytes,SqliteDatabaseLimits::default(),&mut |_|true).unwrap()).unwrap();assert_eq!(project(&actual),d);assert_eq!(actual.slots[0].y.to_bits(),0x7ff0000000000001);assert_eq!(actual.slots[0].pinned_tile_id,Some("".into()));assert_eq!(actual.rules[0].relation,None);assert_eq!(actual.rules[1].relation,Some("".into()));assert!(matches!(actual.tiles[0].media,Wfc2dTileMedia::Empty));assert_eq!(store::ArtifactPack::encode_pack(&actual),store::ArtifactPack::encode_pack(&s));assert_eq!(store::ArtifactDsl::print_dsl(&actual),store::ArtifactDsl::print_dsl(&s));assert_eq!(restore(&project(&Wfc2dSnapshot::default())).unwrap(),Wfc2dSnapshot::default());}
#[test]fn sqlite_snapshot_wfc2d_independent_relations_and_path_edit(){use std::io::Write;use std::process::{Command,Stdio};let bytes=export_sqlite_database(&project(&fixture()),SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let script="import{Database}from'bun:sqlite';const d=Database.deserialize(new Uint8Array(await Bun.stdin.arrayBuffer()));if(d.query('PRAGMA integrity_check').get().integrity_check!=='ok'||d.query('PRAGMA foreign_key_check').all().length)throw Error('integrity');if(d.query('SELECT kind FROM wfc2d_segment ORDER BY ordinal').all().map(r=>r.kind).join(',')!=='Move,Line,Quad,Cubic,Close')throw Error('commands');const pin=d.query('SELECT s.authored_id AS slot,t.authored_id AS tile FROM wfc2d_slot s JOIN wfc2d_tile t ON pinned_tile_id=t.id').get();if(pin.slot!=='box'||pin.tile!=='')throw Error('pin');d.query(\"UPDATE wfc2d_path_color SET red=7 WHERE role='stroke'\").run();await Bun.write(Bun.stdout,d.serialize());";let mut c=Command::new("bun").args(["-e",script]).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();c.stdin.take().unwrap().write_all(&bytes).unwrap();let o=c.wait_with_output().unwrap();assert!(o.status.success(),"{}",String::from_utf8_lossy(&o.stderr));let actual=restore(&import_sqlite_database(&o.stdout,SqliteDatabaseLimits::default(),&mut |_|true).unwrap()).unwrap();if let Wfc2dTileMedia::Vector{paths}=&actual.tiles[2].media{assert_eq!(paths[0].stroke.unwrap().r,7)}else{panic!("media")}}
#[test]fn sqlite_snapshot_wfc2d_corrupt_graph_and_point_shape(){let d=project(&fixture());for n in 0..8{let mut m=d.clone();match n{0=>m.table_mut("wfc2d_rule").unwrap().rows[0].values[4]=SqliteValue::Integer(999),1=>m.table_mut("wfc2d_segment").unwrap().rows[0].values[2]=SqliteValue::Integer(99),2=>m.table_mut("wfc2d_path_color").unwrap().rows[0].values[2]=SqliteValue::Text("unknown".into()),3=>m.table_mut("wfc2d_palette").unwrap().rows[0].values[3]=SqliteValue::Integer(-1),4=>m.table_mut("wfc2d_segment").unwrap().rows[4].values[4]=SqliteValue::Real(1.),5=>m.table_mut("wfc2d_slot_edge").unwrap().rows[0].values[5]=SqliteValue::Integer(999),6=>m.table_mut("wfc2d_slot").unwrap().rows[0].values[8]=SqliteValue::Integer(999),_=>m.table_mut("wfc2d_slot").unwrap().rows[0].values[9]=SqliteValue::Integer(1)};assert!(restore(&m).is_err(),"case {n}");}assert!(fixture().to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|false,SqliteDatabaseLimits::default())).is_err());assert!(Wfc2dSnapshot::from_sqlite_database(&d,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_value_bytes:4,..SqliteDatabaseLimits::default()})).is_err());}
#[test]fn sqlite_snapshot_wfc2d_actual_native_declaration(){let s=fixture();let codec=crate::standards::v1::subsets::any::io::io().native.codec;let provider=codec.snapshot_sqlite.unwrap();let dialect=store::os_io::ArtifactDialect{artifact_kind:"s.wfc.wfc2d".into(),standard:"1".into(),subset:"*".into()};for encoding in [SnapshotEncoding::Binary,SnapshotEncoding::Text]{let actual=(provider.import)("wfc2d",&dialect,project(&s),encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap().value;let expected=match encoding{SnapshotEncoding::Binary=>store::os_io::IoPayload::Binary(store::ArtifactPack::encode_pack(&s)),SnapshotEncoding::Text=>store::os_io::IoPayload::Text(store::ArtifactDsl::print_dsl(&s))};assert_eq!(actual,expected);assert!(s.preflight_sqlite_snapshot_encoding(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_file_bytes:16,..SqliteDatabaseLimits::default()})).is_err());}let wrong=store::os_io::ArtifactDialect{artifact_kind:"s.wfc.wfc2d".into(),standard:"1".into(),subset:"named".into()};assert!(s.validate_sqlite_snapshot_subset(&wrong,&project(&s),&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).is_err());}
